messages.content:
Tool response:
Tool: add_rubric_criterion
Description: Adds a new rubric criterion to the specified assignment in a course.
Requires the course ID, assignment ID, criterion name, weight, max score, and description.
Parameters:
    {
      "type": "object",
      "properties": {
        "course_id": {
          "type": "integer",
          "description": "Internal ID of the course",
          "title": "Course Id"
        },
        "assignment_id": {
          "type": "integer",
          "description": "Internal ID of the assignment",
          "title": "Assignment Id"
        },
        "name": {
          "type": "string",
          "title": "Name",
          "description": "Name of the rubric criterion"
        },
        "weight": {
          "type": "number",
          "maximum": 100.0,
          "minimum": 0.0,
          "title": "Weight",
          "description": "Weight of the criterion as a percentage (0-100)"
        },
        "max_score": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Max Score",
          "description": "Maximum score achievable for this criterion"
        },
        "description": {
          "type": "string",
          "title": "Description",
          "description": "Description of what the criterion evaluates"
        }
      },
      "required": [
        "course_id",
        "assignment_id",
        "name",
        "weight",
        "max_score",
        "description"
      ]
    }
